// Free functions that use the classes above.
int total(const std::vector<Foo0>& v) {
    int sum = 0;
    for (const auto& f : v) {
        sum += f.value();
    }
    return sum;
}

int main() {
    std::vector<Foo0> items;
    for (int i = 0; i < 10; ++i) {
        items.emplace_back();
    }
    std::cout << total(items) << std::endl;
    return 0;
}

